buildGradleAdditions.insert:
repositories {
  maven {
    url 'https://nexus-external.rustore.ru/repository/maven-rustore-exposed'
  }
}

ext.appupdate_type = ''

if (project.hasProperty('rustore_sdk_type')) {
  appupdate_type = rustore_sdk_type
}

dependencies {
  // RuStore AppUpdate
  implementation("ru.rustore.sdk:appupdate:10.5.1$appupdate_type")
  implementation fileTree(include: ["RuStoreUnrealAppUpdate${appupdate_type}.aar"], dir: 'src/main/libs')
}
